local XUiLifeTreeCardGridCard = require("XUi/XUiLifeTree/XUiLifeTreeCard/XUiLifeTreeCardGridCard")
---@class XUiLifeTreeCardGridDivineCard : XUiLifeTreeCardGridCard
---@field _Control XLifeTreeControl
---@field Parent XUiLifeTreeCard
local XUiLifeTreeCardGridDivineCard = XClass(XUiLifeTreeCardGridCard, "XUiLifeTreeCardGridDivineCard")

function XUiLifeTreeCardGridDivineCard:OnStart(catalogId)
    self.CatalogId = catalogId
    
    self:InitComponents()
    self:Refresh()
    self:PlayEnableAnim()
end

function XUiLifeTreeCardGridDivineCard:OnEnable()
end

function XUiLifeTreeCardGridDivineCard:OnDisable()
end

function XUiLifeTreeCardGridDivineCard:OnDestroy()
end

function XUiLifeTreeCardGridDivineCard:InitComponents()
    self.Button:AddEventListener(function() self:OnBtnButtonClick() end)

    self:InitLine()
end

function XUiLifeTreeCardGridDivineCard:GetCardType()
    return XMVCA.XLifeTree.EnumConst.CARD_TYPE.DIVINE
end

function XUiLifeTreeCardGridDivineCard:Refresh()
    self.ImgOffline.gameObject:SetActiveEx(false)
    self.ImgLocked.gameObject:SetActiveEx(false)
    self.EffectUnlock.gameObject:SetActiveEx(false)
    self.PanelUnlockedPositive.gameObject:SetActiveEx(false)
    self.PanelUnlockedReverse.gameObject:SetActiveEx(false)
    
    -- 角色状态
    local unlockCount, state = XMVCA.XLifeTree:GetCharacterStateByCatalogId(self.CatalogId) -- 解锁次数和状态
    local divineType = self._Control:GetCharacterDivineState(self.CatalogId) -- 当前神卡类型
    local isOffline = state == XMVCA.XLifeTree.EnumConst.CHARACTER_STATE.OFFLINE -- 是否未上线
    local isUnlockable = state == XMVCA.XLifeTree.EnumConst.CHARACTER_STATE.NEXT_UNLOCKABLE -- 是否可解锁下一状态

    -- 刷新UI
    local catalogConfig = self._Control:GetLifeTreeCharacterCatalogConfigById(self.CatalogId)
    if isOffline then
        self.ImgOffline.gameObject:SetActiveEx(true)
    elseif divineType == XMVCA.XLifeTree.EnumConst.DIVINE_TYPE.POSITIVE then
        self.PanelUnlockedPositive.gameObject:SetActiveEx(true)
        self.PanelUnlockedPositive:GetObject("RawImgCard"):SetRawImage(catalogConfig.CardIcons[unlockCount])
        self.PanelUnlockedPositive:GetObject("TxtName").text = catalogConfig.Name
        self.PanelUnlockedPositive:GetObject("TxtDesc").text = catalogConfig.Descs[unlockCount]
    elseif divineType == XMVCA.XLifeTree.EnumConst.DIVINE_TYPE.REVERSE then
        self.PanelUnlockedReverse.gameObject:SetActiveEx(true)
        self.PanelUnlockedReverse:GetObject("RawImgCard"):SetRawImage(catalogConfig.CardIcons[unlockCount])
        self.PanelUnlockedReverse:GetObject("TxtName").text = catalogConfig.Name
        self.PanelUnlockedReverse:GetObject("TxtDesc").text = catalogConfig.Descs[unlockCount]
    else
        self.ImgLocked.gameObject:SetActiveEx(true)
    end

    -- 可解锁特效
    self.EffectUnlock.gameObject:SetActiveEx(isUnlockable)
end

function XUiLifeTreeCardGridDivineCard:OnBtnButtonClick()
    if self.Parent:IsCardInAnimPlaying() then return end

    local unlockCount, state = XMVCA.XLifeTree:GetCharacterStateByCatalogId(self.CatalogId) -- 解锁次数和状态
    if state == XMVCA.XLifeTree.EnumConst.CHARACTER_STATE.OFFLINE then 
        local config = self._Control:GetLifeTreeClientConfigConfigById("OfflineTips")
        XUiManager.TipError(config.Values[1])
    elseif state == XMVCA.XLifeTree.EnumConst.CHARACTER_STATE.NEXT_UNLOCKABLE then
        local nextUnlockIndex = unlockCount + 1
        XMVCA.XLifeTree:RequestLifeTreeUnlockCharacter(self.CatalogId, nextUnlockIndex, function()
            self:OnCharacterUnlock(nextUnlockIndex) -- 解锁成功回调
        end)
    elseif state == XMVCA.XLifeTree.EnumConst.CHARACTER_STATE.NEXT_LOCKED then
        XLuaUiManager.Open("UiLifeTreeUnlockType", self.CatalogId)
    end
end

-- 解锁成功回调
function XUiLifeTreeCardGridDivineCard:OnCharacterUnlock(unlockIndex)
    -- 背景动画
    local catalogConfig = self._Control:GetLifeTreeCharacterCatalogConfigById(self.CatalogId)
    local characterConfig = self._Control:GetLifeTreeCharacterConfigById(catalogConfig.CharacterId)
    local uiUnlockAnim = characterConfig.UiLifeTreeCardUnlockAnims[unlockIndex]
    if uiUnlockAnim then
        self.Parent:PlayAnimationWithMask(uiUnlockAnim)
    end
    -- 卡牌动画
    local gridUnlockAnim = characterConfig.GridDivineCardUnlockAnims[unlockIndex]
    if gridUnlockAnim then
        self.IsAnimPlaying = true
        self.Parent:PlayNonDivineCardsAnimHide()
        self:PlayAnimationWithMask(gridUnlockAnim, function()
            -- 超过1个状态的神卡解锁，自动切换到下一状态描述
            if unlockIndex > 1 then
                self.Parent:OnBtnSwitchClick()
            end
            self.Parent:PlayNonDivineCardsAnimShow()
            self.Parent:RefreshBtnTask()
            self.IsAnimPlaying = false
        end)
    end

    self:Refresh()
end

return XUiLifeTreeCardGridDivineCard
